(()=>{'use strict';const D=window.ActionTeachingData,$=id=>document.getElementById(id),params=new URLSearchParams(location.search);const mode=['match','show','name'].includes(params.get('mode'))?params.get('mode'):'match',method=params.get('method')==='immediate'?'immediate':'wait',titles={match:'Eylem eşleme',show:'Eylem gösterme',name:'Eylem ismi söyleme'};
let itemId=D.items[0].id,level=1,index=0,trials=[],token=0,timer=null,rec=null,busy=false,paused=false,prompted=false,misses=0,selected=false,drag=null,ignoreClick=false,phase='setup',pendingAdvance=false,results=[],lastText='';
const rewards=['Aferin!','Harikasın!','Çok güzel!','Bravo!','Süpersin!','Çok iyi yaptın!','Mükemmel!','Başardın!','Ne güzel yaptın!','Çok başarılısın!','Harika bir cevap!','Çok dikkatliydin!','Tebrik ederim!','Şahane!','Çok güzel ilerliyorsun!'];
const current=()=>trials[index],active=()=>!paused&&!$('work').hidden;const videos=()=>[...$('work').querySelectorAll('video')].filter(v=>!v.hidden);const stopRec=()=>{const old=rec;rec=null;if(old){old.onresult=old.onend=old.onerror=old.onstart=old.onspeechstart=old.onprocessing=null;old.abort();}};
function clear(){clearTimeout(timer);timer=null;stopRec();}function cancel(){token++;clear();speechSynthesis.cancel();}
function controls(disabled){$('source').disabled=disabled;$('targets').querySelectorAll('button').forEach(b=>b.disabled=disabled);}
function say(text,done){clear();busy=true;controls(true);$('feedback').textContent=text;const run=token;const utterance=new SpeechSynthesisUtterance(text);utterance.lang='tr-TR';utterance.rate=.9;const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('tr'));if(voice)utterance.voice=voice;utterance.onend=()=>{if(run===token&&active()){busy=false;controls(false);done?.();}};utterance.onerror=()=>{if(run!==token)return;busy=false;controls(false);$('feedback').textContent='Seslendirme tamamlanamadı. İpucu düğmesiyle yeniden deneyin.';};speechSynthesis.speak(utterance);}
function media(item){return`<video muted playsinline loop preload="metadata" poster="./assets/actions/videos/${item.video.poster}" src="./assets/actions/videos/${item.video.file}" aria-label="${item.name}"></video>`;}
async function play(){try{await Promise.all(videos().map(v=>{v.muted=true;v.currentTime=0;return v.play();}));return true;}catch{return false;}}
function setup(){cancel();phase='setup';$('work').hidden=$('summary').hidden=true;$('setup').hidden=false;$('pause').hidden=true;$('title').textContent=titles[mode];$('methodLabel').textContent=method==='immediate'?'Eşzamanlı öğretim':'4 saniye sabit bekleme süreli öğretim';$('items').innerHTML=D.items.map(i=>{const poster=window.ActionVideoLibrary.find(v=>v.id===i.id)?.variants[0]?.poster;return `<button type="button" data-item="${i.id}" class="action-choice ${i.id===itemId?'selected':''}" aria-pressed="${i.id===itemId}">${poster?`<img src="./assets/actions/videos/${poster}" alt="" loading="lazy" decoding="async" width="240" height="135">`:''}<span>${i.name}</span></button>`;}).join('');$('levelHeading').textContent=`${D.items.find(i=>i.id===itemId).name} · Seviye seç`;$('levels').innerHTML=D.stages[mode].map((s,i)=>`<button type="button" data-level="${i+1}" class="level-choice"><span class="level-number" aria-hidden="true">${i+1}</span><span class="level-copy"><strong>Seviye ${i+1}</strong><span>${s.title}</span></span><span class="trial-count">5 deneme</span></button>`).join('');}

async function start(newLevel){if(mode==='name'){try{await window.LocalMicrophone.ensure();const response=await fetch('/api/status');const info=await response.json();if(!response.ok||!info.ready)throw Error(info.message||'Dinleme hizmeti hazır değil.');}catch(error){$('micNotice').textContent='Dinleme başlatılamadı. '+error.message;return;}}level=newLevel;trials=D.block(mode,itemId,level);index=0;results=[];$('setup').hidden=$('summary').hidden=true;$('work').hidden=false;$('pause').hidden=false;render();}
function render(){cancel();phase='instruction';paused=false;pendingAdvance=false;prompted=false;misses=0;selected=false;drag=null;lastText='';ignoreClick=false;$('pause').textContent='Mola';$('source').style.transform='';$('source').className='source';const t=current();$('counter').textContent=`Seviye ${level} · ${index+1} / 5`;$('instruction').textContent=mode==='name'?'Ne yapıyor? Söyle.':`${t.item.instruction} ${mode==='match'?'eşle':'göster'}.`;$('heard').textContent='';$('feedback').textContent='';$('targets').replaceChildren();$('nameVideo').hidden=mode!=='name';$('source').hidden=mode!=='match';$('sourceNote').hidden=mode!=='match';
if(mode==='name'){$('nameVideo').src=`./assets/actions/videos/${t.item.video.file}`;$('nameVideo').poster=`./assets/actions/videos/${t.item.video.poster}`;}else{t.options.forEach(item=>{const button=document.createElement('button');button.type='button';button.className='target';button.dataset.id=item.id;button.setAttribute('aria-label',`${item.name} kartı`);button.innerHTML=media(item);button.onclick=()=>{if(mode==='show'||selected)answer(item.id);};$('targets').append(button);});$('source').innerHTML=mode==='match'?media(t.item):'';}
controls(true);$('feedback').textContent='Videolar hazırlanıyor…';const run=token;play().then(ready=>{if(run!==token||!active())return;if(!ready){$('feedback').textContent='Video açılamadı. Ana menüye dönüp yeniden deneyin.';return;}say($('instruction').textContent,()=>{phase='response';if(method==='immediate')hint();else if(mode==='name')listen();else timer=setTimeout(()=>hint(),4000);});});}
function hint(wrong=false){if(!active()||pendingAdvance)return;clear();prompted=true;phase='prompt';if(drag){drag=null;$('source').style.transform='';$('source').classList.remove('dragging');}if(mode==='name'){say(`${current().item.model}. Şimdi sen söyle.`,()=>{phase='response';listen();});return;}$('targets').querySelectorAll('button').forEach(b=>b.classList.toggle('hint',b.dataset.id===current().item.id));$('source').classList.add('hint');const text=`${wrong?'Bu eşleşme olmadı. ':''}${current().item.model}. ${mode==='match'?'Alttaki videoyu gösterilen eşiyle eşle.':'Gösterilen eyleme dokun.'}`;say(text,()=>phase='response');}
function advance(){phase='reward';const run=token;timer=setTimeout(()=>{if(run!==token||!active())return;pendingAdvance=false;index++;if(index<5)render();else summary();},800);}
function success(){if(!active()||busy||pendingAdvance)return;clear();pendingAdvance=true;results.push(prompted||misses?'prompted':'independent');$('targets').querySelectorAll('button').forEach(b=>b.classList.toggle('good',b.dataset.id===current().item.id));say(rewards[Math.floor(Math.random()*rewards.length)],advance);}
function answer(id){if(!active()||busy||pendingAdvance)return;selected=false;$('source').classList.remove('selected');if(id===current().item.id){success();return;}misses++;hint(true);}
function miss(kind='wrong'){if(!active()||busy||pendingAdvance)return;clear();misses++;prompted=true;const text=D.correction(current().item,lastText,kind,misses<2);if(misses>=2){results.push('incorrect');pendingAdvance=true;say(text,advance);}else say(text,()=>{phase='response';listen();});}
function listen(){clear();if(!active())return;phase='response';const Recognition=window.LocalSpeechRecognition;if(!Recognition){$('feedback').textContent='Bu cihazda dinleme sistemi kullanılamıyor.';return;}const run=token,instance=new Recognition();rec=instance;let spoke=false;const valid=()=>run===token&&rec===instance&&active();const failure=text=>{if(!valid())return;clear();$('feedback').textContent=text+' Çocuk için hata kaydedilmedi. İpucuyla yeniden deneyin.';};instance.onstart=()=>{if(!valid())return;$('feedback').textContent=prompted?'Şimdi sen söyle. Dinliyorum…':'Dinliyorum… 4 saniye';timer=setTimeout(()=>{if(valid()&&!spoke)miss('uncertain');},prompted?12000:4000);};instance.onspeechstart=()=>{if(!valid()||spoke)return;spoke=true;clearTimeout(timer);timer=setTimeout(()=>failure('Yanıt netleşmedi.'),30000);};instance.onprocessing=()=>{if(valid()){$('feedback').textContent='Yanıt çözümleniyor…';clearTimeout(timer);timer=setTimeout(()=>failure('Dinleme hizmeti yanıt vermedi.'),30000);}};instance.onresult=e=>{if(!valid())return;const result=e.results[e.resultIndex];if(!result?.isFinal)return;lastText=result[0].transcript;$('heard').textContent='Duyulan: '+window.NamingRules.safeText(lastText);const verdict=D.judge(lastText,current().item);if(verdict==='correct')success();else if(verdict==='uncertain')failure('Söyleyiş anlaşılamadı.');else miss(verdict);};instance.onerror=()=>failure('Mikrofon veya dinleme bağlantısı çalışmadı.');instance.onend=()=>{if(valid())failure('Net bir yanıt alınamadı.');};instance.start();}
function summary(){cancel();phase='summary';videos().forEach(v=>v.pause());$('work').hidden=true;$('summary').hidden=false;$('pause').hidden=true;$('next').hidden=level>=D.stages[mode].length;$('gameNote').hidden=true;const stats={independent:results.filter(r=>r==='independent').length,prompted:results.filter(r=>r==='prompted').length,incorrect:results.filter(r=>r==='incorrect').length};$('totals').textContent=`${stats.independent} bağımsız doğru · ${stats.prompted} ipucuyla doğru · ${stats.incorrect} tamamlanamadı`;if(parent!==window)parent.postMessage({type:'action-teaching-complete',mode,level,stats},location.origin);}
function menu(){cancel();videos().forEach(v=>v.pause());if(parent!==window)parent.postMessage({type:'action-preview-menu'},location.origin);else location.href='./';}
$('items').onclick=e=>{const b=e.target.closest('[data-item]');if(b){itemId=b.dataset.item;setup();$('items').querySelector(`[data-item="${itemId}"]`).focus({preventScroll:true});}};$('levels').onclick=e=>{const b=e.target.closest('[data-level]');if(b)start(Number(b.dataset.level));};$('help').onclick=()=>{if(!busy&&active())hint();};$('menu').onclick=$('summaryMenu').onclick=menu;$('next').onclick=()=>start(level+1);$('game').onclick=()=>$('gameNote').hidden=false;
$('source').onclick=()=>{if(ignoreClick){ignoreClick=false;return;}if(!busy&&active()){selected=true;$('source').classList.add('selected');}};
$('source').onpointerdown=e=>{if(!active()||busy||e.button>0)return;$('source').setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};};$('source').onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>8)drag.moved=true;if(drag.moved){$('source').classList.add('dragging');$('source').style.transform=`translate(${dx}px,${dy}px)`;}};
function release(e){const gesture=drag;drag=null;$('source').style.transform='';$('source').classList.remove('dragging');if($('source').hasPointerCapture(e.pointerId))$('source').releasePointerCapture(e.pointerId);if(gesture?.moved&&e.type==='pointerup'){ignoreClick=true;setTimeout(()=>ignoreClick=false,0);const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.target');if(target)answer(target.dataset.id);}}$('source').onpointerup=$('source').onpointercancel=release;
$('pause').onclick=()=>{if(paused){paused=false;$('pause').textContent='Mola';play();if(pendingAdvance){say('Devam ediyoruz.',advance);}else if(prompted||method==='immediate')hint();else{say($('instruction').textContent,()=>{if(mode==='name')listen();else timer=setTimeout(()=>hint(),4000);});}}else{paused=true;cancel();videos().forEach(v=>v.pause());drag=null;$('source').style.transform='';$('source').classList.remove('dragging');$('pause').textContent='Devam et';$('feedback').textContent='Mola. Hazır olduğunda devam et.';}};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&active()&&!paused)$('pause').click();});window.addEventListener('pagehide',()=>{cancel();videos().forEach(v=>v.pause());});setup();})();
